def page(fn,title,desc,body,extra=''):
    h=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex"><title>{title} · Talencia concept</title><meta name="description" content="{desc}"><link rel="icon" href="assets/talencia-logo-v2.png"><link rel="stylesheet" href="site.css?v={V}"></head><body>{nav(fn)}{body}{FOOT}{extra}</body></html>'
    open(fn,'w').write(h)
def S(inner,cls='',id=''):return f'<section class="{cls}"{f" id={id}" if id else ""}><div class="wrap rv">{inner}</div></section>'
def hero(eb,h1,lead,acts,cls='c'):return S(f'<p class="eyebrow">{eb}</p><h1>{h1}</h1><p class="lead">{lead}</p><div class="acts">{acts}</div>',cls)
def tiles(items,n=3,big=False):return f'<div class="tiles{" t"+str(n) if n!=2 else ""}">'+''.join(f'<div class="tile{" big" if big else ""}"><h3>{t}</h3><p>{d}</p>{f"<a class=more href={l}>{lt}</a>" if l else ""}</div>' for t,d,l,lt in [(i+(None,None))[:4] if len(i)==2 else i for i in items])+'</div>'
def steps(items):return '<div class="steps">'+''.join(f'<div><h3>{t}</h3><p>{d}</p></div>' for t,d in items)+'</div>'
def form(id,fields,btn,note='Demo form: nothing is sent.'):
    return f'<form class="form" data-demo id="{id}" novalidate>{fields}<p style="margin-top:22px"><button class="btn" type="submit">{btn}</button></p><p style="font-size:13px;color:var(--mute)"><span class="demo">Demo</span> {note}</p><div class="ok-msg" tabindex="-1" role="status">Thanks. In the live version a recruiter follows up the same day.</div></form>'
def inp(lbl,name,t='text',req=False,ph=''):
    i=name;return f'<label for="{i}">{lbl}{" *" if req else ""}</label><input id="{i}" name="{name}" type="{t}"{" required" if req else ""}{f" placeholder=\"{ph}\"" if ph else ""}{" inputmode=tel autocomplete=tel" if t=="tel" else ""}>'
def chks(lbl,name,opts,t='checkbox'):return f'<fieldset style="border:0;padding:0;margin:14px 0 0"><legend style="font-weight:600;font-size:14px;margin-bottom:8px">{lbl}</legend><div class="chk">'+''.join(f'<label><input type="{t}" name="{name}" value="{o}"> {o}</label>' for o in opts)+'</div></fieldset>'
WORK=chks('What kind of work?','work',['Temp shifts','Temp-to-hire','Permanent placement'])
def phone(inner):return f'<div class="phone" role="img" aria-label="Talencia app screen, demo"><div class="screen">{inner}</div></div>'
