RISK=tiles([('W-2 employer of record','Every professional we place is on our payroll, not yours.'),('Workers\u2019 comp covered','Coverage is handled on our side for every shift.'),('Benefits on our books','Health, dental, vision and 401(k) admin stay with us.')])
def clientpage(fn,kind,h1,unit,roles):
    b=hero(f'For {kind}',h1,'Fill a gap tomorrow or hire for the long run, with one partner that carries the employer paperwork.','<a class="btn" href="request-talent.html">Request talent</a><a class="more" href="#math">Do the math</a>')
    b+=S('<p class="eyebrow">How we help</p><h2>Cover tomorrow. Hire for years.</h2>'+tiles([('Temporary coverage','Vetted pros for a single day or a whole season.','request-talent.html','Request a shift'),('Temp-to-hire','Try the fit on real days before you commit.','request-talent.html','Start a trial'),('Permanent placement','We search, screen and present finalists.','request-talent.html','Start a search')],3,True),'c soft')
    b+=S('<p class="eyebrow">Roles we fill</p><h2>'+' · '.join(roles)+'</h2>','c')
    b+=f'<section class="c" id="math"><div class="wrap rv"><p class="eyebrow">The math</p><h2>What does an empty {unit} cost?</h2>{calc(unit)}</div></section>'
    b+=S('<p class="eyebrow">Risk, off your plate</p><h2>You get the help. We carry the obligations.</h2>'+RISK,'c dark')
    b+=S('<h2>Tell us who you\u2019re missing.</h2><div class="acts"><a class="btn teal" href="request-talent.html">Request talent</a><a class="more" href="https://clientportal.staffupapp.com/talencia/login">Client portal login</a></div>','c')
    page(fn,f'Staffing for {kind}',f'Talencia staffing for {kind}',b)
BEN=[('Medical insurance','Plans for full-time W-2 professionals.'),('Dental coverage','Because you know how much it matters.'),('Vision coverage','Included in the benefits package.'),('Life insurance','Peace of mind for your family.'),('Continuing education','CE support to keep growing.'),('Shift rewards','Points for every shift you work.'),('Flexible scheduling','Pick the days that fit your life.'),('Workers\u2019 comp included','Covered on every assignment.')]
def propage(fn,kind,roles):
    b=hero(f'For {kind} professionals','Great work.<br>On your terms.','Choose your shifts, keep your benefits and have a real recruiter in your corner.','<a class="btn" href="join.html">Join the network</a><a class="more" href="jobs.html">Browse jobs</a>')
    b+=S('<p class="eyebrow">Benefits &amp; lifestyle</p><h2>Your license. Your schedule.</h2>'+'<div class="tiles t4">'+''.join(f'<div class="tile"><h3 style="font-size:18px">{t}</h3><p>{d}</p></div>' for t,d in BEN)+'</div><p style="color:var(--mute);margin-top:22px">Insurance benefits for full-time W-2 professionals, plus a 401(k).</p>','c soft')
    b+=S('<div class="split"><div><p class="eyebrow">Shift rewards</p><h2>Work more. Earn more.</h2><p class="lead" style="margin-left:0">Every hour stacks points you can spend on CE, care and the things that matter.</p><a class="more" href="rewards.html">Learn more about Rewards</a></div>'+APPSCREEN+'</div>')
